import { Sprite, Texture } from 'pixi.js';

import { Slide } from './base-slide';
import { ISliderFeatures, SlideManager } from './slide-manager';

export interface IGraphicalSlideManConfig {
    features?: Partial<ISliderFeatures>;
    arrowScale?: number;
    arrowXOffset?: number;
    xPadding?: number;
    slideWidthMultiplier?: number;
    slideHeightMultiplier?: number;
    slideYOffsetMultiplier?: number;
    slideXOffsetMultiplier?: number;
    arrowVisibilityCallback?: () => boolean;
}

export class GraphicalSlideManager extends SlideManager {
    private arrowScale: number;
    private arrowXOffset: number;
    private xPadding: number;
    private slideWidthMultiplier: number;
    private slideHeightMultiplier: number;
    private slideYOffsetMultiplier: number;
    private slideXOffsetMultiplier: number;

    private background: Sprite;
    private leftArrow!: Sprite;
    private rightArrow!: Sprite;
    private shouldShowArrows: () => boolean;

    constructor(slides: Slide[], textures: { background: Texture, arrow: Texture }, config: IGraphicalSlideManConfig = {}) {
        super(slides, config.features, false);

        this.arrowScale = config.arrowScale ?? 1;
        this.arrowXOffset = config.arrowXOffset ?? 0;
        this.xPadding = config.xPadding ?? 50;
        this.slideWidthMultiplier = config.slideWidthMultiplier ?? 1;
        this.slideHeightMultiplier = config.slideHeightMultiplier ?? 1;
        this.slideYOffsetMultiplier = config.slideYOffsetMultiplier ?? 0;
        this.slideXOffsetMultiplier = config.slideXOffsetMultiplier ?? 0;

        if (config.arrowVisibilityCallback) {
            this.shouldShowArrows = config.arrowVisibilityCallback;
        } else {
            this.shouldShowArrows = () => true;
        }

        this.background = new Sprite(textures.background);
        this.background.anchor.set(0.5);
        super.sizeComponents(this.background.width,
            this.background.height,
            this.slideWidth,
            this.slideHeight,
            { x: this.slideXOffset, y: this.slideYOffset });

        this.createArrows(textures.arrow);
        this.addChildren();
    }

    public resize(width: number, height: number): void {
        this.leftArrow.visible = this.slides.length <= 1 ? false : this.shouldShowArrows();
        this.rightArrow.visible = this.slides.length <= 1 ? false : this.shouldShowArrows();

        const widthScale = width / this.baseWidth;
        const heightScale = height / this.baseHeight;
        this.scale.set(Math.min(widthScale, heightScale));
    }

    public updateBackground(background: Texture): void {
        this.background.texture = background;
        this.background.anchor.set(0.5);

        super.sizeComponents(this.background.width,
            this.background.height,
            this.slideWidth,
            this.slideHeight,
            { x: this.slideXOffset, y: this.slideYOffset });

        this.leftArrow.x = -((this.background.width * 0.5) + this.arrowXOffset);
        this.rightArrow.x = (this.background.width * 0.5) + this.arrowXOffset;
    }

    public setNewSlides(slides: Slide[]): void {
        this.killTransitionTweens();
        this.removeChildren();

        this.leftArrow.visible = slides.length <= 1 ? false : this.shouldShowArrows();
        this.rightArrow.visible = slides.length <= 1 ? false : this.shouldShowArrows();

        this.slides = slides;
        this.currentSlideIndex = 0;
        this.slides.forEach((slide) => { slide.mask = this.slideMask; });
        this.buildControls();

        super.sizeComponents(this.background.width,
            this.background.height,
            this.slideWidth,
            this.slideHeight,
            { x: this.slideXOffset, y: this.slideYOffset });

        this.addChildren();
    }

    public onShow(): void {
        if (this.slides.length <= 1) { return; }
        this.startAutoSlideTimeout();
        this.enableInteractions();
    }

    public onHide(): void {
        this.clearAutoSlideTimeout();
        this.disableInteractions();
    }

    public disableInteractions(): void {
        this.leftArrow.cursor = undefined;
        this.leftArrow.alpha = 0.5;

        this.rightArrow.cursor = undefined;
        this.rightArrow.alpha = 0.5;

        this.leftArrow.interactive = false;
        this.rightArrow.interactive = false;

        super.disableInteractions();
    }

    public enableInteractions(): void {
        this.leftArrow.cursor = 'pointer';
        this.leftArrow.alpha = 1;

        this.rightArrow.cursor = 'pointer';
        this.rightArrow.alpha = 1;

        this.leftArrow.interactive = true;
        this.rightArrow.interactive = true;

        super.enableInteractions();
    }

    protected addChildren(): void {
        this.addChild(this.background);
        super.addChildren();
        this.addChild(this.leftArrow, this.rightArrow);
    }

    private createArrows(texture: Texture): void {
        this.leftArrow = new Sprite(texture);
        this.leftArrow.x = -((this.background.width * 0.5) + this.arrowXOffset);
        this.leftArrow.anchor.set(0, 0.5);
        this.leftArrow.scale.set(-this.arrowScale, this.arrowScale);

        this.rightArrow = new Sprite(texture);
        this.rightArrow.x = (this.background.width * 0.5) + this.arrowXOffset;
        this.rightArrow.anchor.set(0, 0.5);
        this.rightArrow.scale.set(this.arrowScale);

        this.leftArrow.on('pointertap', () => this.goToPreviousSlide(), this);
        this.rightArrow.on('pointertap', () => this.goToNextSlide(), this);

        this.leftArrow.interactive = true;
        this.rightArrow.interactive = true;
        this.leftArrow.cursor = 'pointer';
        this.rightArrow.cursor = 'pointer';
    }

    /** Returns the width of the background texture, includes the arrows widths if they are visible */
    private get baseWidth(): number {
        let width = this.background.texture.width;
        if (this.shouldShowArrows()) {
            width += (this.leftArrow.texture.width + this.rightArrow.texture.width) * this.arrowScale;
            width += this.arrowXOffset * 2;
            width += this.xPadding * 2;
        }

        return width;
    }

    /** Returns the height of the background texture */
    private get baseHeight(): number {
        return this.background.texture.height;
    }

    private get slideWidth(): number {
        return this.background.texture.width * this.slideWidthMultiplier;
    }

    private get slideHeight(): number {
        return this.background.texture.height * this.slideHeightMultiplier;
    }

    private get slideXOffset(): number {
        return this.background.texture.width * this.slideXOffsetMultiplier;
    }

    private get slideYOffset(): number {
        return this.background.texture.height * this.slideYOffsetMultiplier;
    }
}
